DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_1','Beyond the Sky[NEWLINE]Exploration-driven mobile land warfare[NEWLINE]Domination; Science or Culture supported by development[NEWLINE][NEWLINE]Earn Joy through productive exploration and survivable combat, then use Beyond the Sky as a planned operational window. The meter rewards activity; it does not make a poorly supported mounted army good at every task.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_2','Scout safely and keep a defensive core. Use exploration to build Joy without abandoning improvements and research. Prepare the Horseman timing only if the map and strategic resources support it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_3','Use Prodigies to choose fights, reveal approaches and retreat after attacking. Training Rooms contribute infrastructure and Joy, while the first movement window helps new units deploy. Keep siege and ranged support for defended cities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_4','Stage forces and an objective before the meter reaches its burst. Spend the six-turn window on decisive movement and attacks, then plan for the reset to 25 Joy rather than leaving an exhausted offensive unsupported.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_5','- Exploration and combat progression both feed the signature meter.[NEWLINE]- Fast Prodigies can select engagements and threaten exposed logistics.[NEWLINE]- Beyond the Sky gives a broad land-army mobility and attack window.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_6','- The burst is temporary and is followed by a substantial meter rebuild.[NEWLINE]- Prodigies have an explicit city-attack penalty.[NEWLINE]- The early mounted plan is still constrained by normal resources, counters and support needs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_7','- Protect caravans and vulnerable support with layered zones and anti-mounted forces.[NEWLINE]- Avoid isolated high-experience targets that a Prodigy can exploit.[NEWLINE]- Preserve the main defense through the burst, then punish an overextended army after it ends.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_8','- Using Prodigies alone to assault strong cities.[NEWLINE]- Reaching 100 Joy with the army still travelling or healing.[NEWLINE]- Assuming the 50-Joy movement effect applies to every land class.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Mobility can deny repeated attacks against the same Project and expose wounded climbers.[NEWLINE][NEWLINE]Pigeon Republic: Caravan routes and lightly defended origins are natural targets for a mobile land force.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Unrung Bell: Prepared friendly-land defenders and inherited Pikeman counters make a direct mounted breakthrough expensive.[NEWLINE][NEWLINE]The Threshold Court: A defended destination can receive an additional melee defender without using the long route Masaya hoped to exploit.');
