INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_BACKGROUND','Earn Joy through productive exploration and survivable combat, then use Beyond the Sky as a planned operational window. The meter rewards activity; it does not make a poorly supported mounted army good at every task.');
