INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_STRATEGY','Earn Joy through productive exploration and survivable combat, then use Beyond the Sky as a planned operational window. The meter rewards activity; it does not make a poorly supported mounted army good at every task.[NEWLINE][NEWLINE]Scout safely and keep a defensive core. Use exploration to build Joy without abandoning improvements and research. Prepare the Horseman timing only if the map and strategic resources support it.[NEWLINE][NEWLINE]Use Prodigies to choose fights, reveal approaches and retreat after attacking. Training Rooms contribute infrastructure and Joy, while the first movement window helps new units deploy. Keep siege and ranged support for defended cities.[NEWLINE][NEWLINE]Stage forces and an objective before the meter reaches its burst. Spend the six-turn window on decisive movement and attacks, then plan for the reset to 25 Joy rather than leaving an exhausted offensive unsupported.');
