INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_LEADER_TEXT_1','Beyond the Sky[NEWLINE]Exploration-driven mobile land warfare[NEWLINE]Domination; Science or Culture supported by development[NEWLINE][NEWLINE]Earn Joy through productive exploration and survivable combat, then use Beyond the Sky as a planned operational window. The meter rewards activity; it does not make a poorly supported mounted army good at every task.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_LEADER_TEXT_2','Scout safely and keep a defensive core. Use exploration to build Joy without abandoning improvements and research. Prepare the Horseman timing only if the map and strategic resources support it.[NEWLINE][NEWLINE]Use Prodigies to choose fights, reveal approaches and retreat after attacking. Training Rooms contribute infrastructure and Joy, while the first movement window helps new units deploy. Keep siege and ranged support for defended cities.[NEWLINE][NEWLINE]Stage forces and an objective before the meter reaches its burst. Spend the six-turn window on decisive movement and attacks, then plan for the reset to 25 Joy rather than leaving an exhausted offensive unsupported.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_MASAYABEYONDSKY_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Mobility can deny repeated attacks against the same Project and expose wounded climbers.[NEWLINE][NEWLINE]Pigeon Republic: Caravan routes and lightly defended origins are natural targets for a mobile land force.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Unrung Bell: Prepared friendly-land defenders and inherited Pikeman counters make a direct mounted breakthrough expensive.[NEWLINE][NEWLINE]The Threshold Court: A defended destination can receive an additional melee defender without using the long route Masaya hoped to exploit.');
